## 6. Rate Limiting

### Vulnerabilities

- **Brute Force Attacks**: No limits on authentication attempts
- **DDoS Attacks**: Unlimited requests consuming resources
- **Credential Stuffing**: Automated account takeover attempts
- **API Abuse**: Scrapers and bots overwhelming the service
- **Spam**: Unlimited form submissions or data creation

### Best Practices

```javascript
const express = require('express');
const rateLimit = require('express-rate-limit');
const RedisStore = require('rate-limit-redis');
const redis = require('redis');
const app = express();

// ============================================
// BASIC RATE LIMITING
// ============================================

// GOOD: General API rate limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
  skip: (req) => {
    // Skip rate limiting for certain IPs (internal, trusted)
    return req.ip === '127.0.0.1';
  },
});

app.use(limiter);

// ============================================
// STRICTER RATE LIMITING FOR SENSITIVE ENDPOINTS
// ============================================

// GOOD: Stricter limits for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 attempts per 15 minutes
  message: 'Too many login attempts, please try again later.',
  skipSuccessfulRequests: true, // Don't count successful requests
  skipFailedRequests: false, // Count failed requests
});

app.post('/api/login', authLimiter, (req, res) => {
  // Handle login
  res.json({ token: '...' });
});

app.post('/api/register', authLimiter, (req, res) => {
  // Handle registration
  res.json({ user: {} });
});

// GOOD: Rate limiting for password reset
const passwordResetLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 3, // 3 attempts per hour
  skipSuccessfulRequests: true,
});

app.post('/api/forgot-password', passwordResetLimiter, (req, res) => {
  // Handle password reset
  res.json({ message: 'Reset email sent' });
});

// ============================================
// REDIS-BACKED RATE LIMITING (FOR DISTRIBUTED SYSTEMS)
// ============================================

const redisClient = redis.createClient({
  host: process.env.REDIS_HOST,
  port: process.env.REDIS_PORT,
  password: process.env.REDIS_PASSWORD,
});

// GOOD: Use Redis store for rate limiting across multiple servers
const redisLimiter = rateLimit({
  store: new RedisStore({
    client: redisClient,
    prefix: 'rate-limit:', // Key prefix in Redis
  }),
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/api/', redisLimiter);

// ============================================
// RATE LIMITING BY USER ID (INSTEAD OF IP)
// ============================================

// GOOD: Rate limit by user ID for authenticated requests
const userLimiter = rateLimit({
  store: new RedisStore({
    client: redisClient,
    prefix: 'user-rate-limit:',
  }),
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 1000, // 1000 requests per hour per user
  keyGenerator: (req) => {
    // Use user ID instead of IP for authenticated users
    return req.user ? req.user.id : req.ip;
  },
});

app.use('/api/user', userLimiter);

// ============================================
// CUSTOM RATE LIMITING LOGIC
// ============================================

// GOOD: Implement custom rate limiting with varying limits
const customLimiter = (req, res, next) => {
  // Different limits for different endpoints
  let limit, windowMs;

  if (req.path === '/api/search') {
    limit = 30; // 30 requests per 5 minutes
    windowMs = 5 * 60 * 1000;
  } else if (req.path === '/api/export') {
    limit = 5; // 5 requests per hour
    windowMs = 60 * 60 * 1000;
  } else {
    limit = 100; // 100 requests per 15 minutes
    windowMs = 15 * 60 * 1000;
  }

  // Apply rate limiting with determined limits
  rateLimit({
    windowMs,
    max: limit,
    standardHeaders: true,
    legacyHeaders: false,
  })(req, res, next);
};

app.use(customLimiter);

// ============================================
// SLIDING WINDOW RATE LIMITING
// ============================================

// GOOD: Implement sliding window counter
function createSlidingWindowLimiter(maxRequests, windowMs) {
  const requests = new Map();

  return (req, res, next) => {
    const key = req.ip;
    const now = Date.now();
    const windowStart = now - windowMs;

    if (!requests.has(key)) {
      requests.set(key, []);
    }

    let timestamps = requests.get(key);
    timestamps = timestamps.filter(t => t > windowStart);

    if (timestamps.length >= maxRequests) {
      const resetTime = Math.ceil((timestamps[0] + windowMs - now) / 1000);
      res.status(429)
        .set('Retry-After', resetTime)
        .json({ error: 'Too many requests' });
      return;
    }

    timestamps.push(now);
    requests.set(key, timestamps);
    next();
  };
}

const slidingLimiter = createSlidingWindowLimiter(100, 60000); // 100 per minute
app.use('/api/', slidingLimiter);

// ============================================
// ERROR HANDLING FOR RATE LIMITS
// ============================================

// GOOD: Custom error handler for rate limit exceeded
app.use((err, req, res, next) => {
  if (err.status === 429) {
    return res.status(429).json({
      error: 'Too many requests',
      retryAfter: err.retryAfter,
      message: 'Please wait before making more requests',
    });
  }
  next(err);
});

// BAD: No rate limiting
app.post('/api/login', (req, res) => {
  // Vulnerable to brute force attacks
  res.json({ token: '...' });
});
```

### Rate Limiting Strategy

| Endpoint | Limit | Window | Rationale |
|----------|-------|--------|-----------|
| `/api/login` | 5 | 15 min | Prevent brute force |
| `/api/register` | 3 | 24 hr | Prevent spam accounts |
| `/api/forgot-password` | 3 | 1 hr | Prevent abuse |
| `/api/search` | 30 | 5 min | Prevent scraping |
| `/api/export` | 5 | 1 hr | Prevent resource abuse |
| General API | 100-1000 | 15 min | Normal usage |

