## 7. Error Handling

### Vulnerabilities

- **Information Disclosure**: Stack traces and error details leaked to clients
- **Debug Mode Exposure**: Debugging information in production
- **Missing Error Logging**: No audit trail for troubleshooting
- **Generic Errors**: Users unable to understand what went wrong
- **Exception Handling Gaps**: Unhandled errors crashing the application

### Best Practices

```javascript
const express = require('express');
const winston = require('winston');
const app = express();

// ============================================
// LOGGING CONFIGURATION
// ============================================

// GOOD: Configure structured logging
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'api-service' },
  transports: [
    // Log errors to error file
    new winston.transports.File({
      filename: 'logs/error.log',
      level: 'error',
    }),
    // Log all to combined file
    new winston.transports.File({
      filename: 'logs/combined.log',
    }),
    // Log to console in development
    ...(process.env.NODE_ENV !== 'production'
      ? [new winston.transports.Console({
          format: winston.format.simple(),
        })]
      : []),
  ],
});

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

// GOOD: Generic error handler that doesn't expose internals
app.use((err, req, res, next) => {
  // Log full error details server-side
  logger.error({
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
    userId: req.user?.id,
  });

  // Send generic error to client
  const statusCode = err.statusCode || 500;
  const clientError = {
    error: 'An error occurred',
    message: process.env.NODE_ENV === 'production'
      ? 'Something went wrong'
      : err.message,
  };

  // Include error code for client reference
  if (err.code) {
    clientError.code = err.code;
  }

  res.status(statusCode).json(clientError);
});

// ============================================
// CUSTOM ERROR CLASSES
// ============================================

// GOOD: Create custom error classes for different scenarios
class ValidationError extends Error {
  constructor(message, details = {}) {
    super(message);
    this.name = 'ValidationError';
    this.statusCode = 400;
    this.details = details;
  }
}

class NotFoundError extends Error {
  constructor(message) {
    super(message);
    this.name = 'NotFoundError';
    this.statusCode = 404;
  }
}

class UnauthorizedError extends Error {
  constructor(message) {
    super(message);
    this.name = 'UnauthorizedError';
    this.statusCode = 401;
  }
}

class ForbiddenError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ForbiddenError';
    this.statusCode = 403;
  }
}

// ============================================
// SPECIFIC ERROR HANDLERS
// ============================================

// GOOD: Handle validation errors specifically
app.use((err, req, res, next) => {
  if (err instanceof ValidationError) {
    logger.warn({
      message: 'Validation error',
      details: err.details,
      url: req.originalUrl,
    });

    return res.status(400).json({
      error: 'Validation failed',
      message: err.message,
      details: err.details, // Safe to expose validation details
    });
  }
  next(err);
});

// GOOD: Handle not found errors
app.use((err, req, res, next) => {
  if (err instanceof NotFoundError) {
    logger.debug({
      message: 'Resource not found',
      url: req.originalUrl,
    });

    return res.status(404).json({
      error: 'Not found',
      message: err.message,
    });
  }
  next(err);
});

// GOOD: Handle authentication errors
app.use((err, req, res, next) => {
  if (err instanceof UnauthorizedError) {
    logger.warn({
      message: 'Unauthorized access attempt',
      url: req.originalUrl,
      ip: req.ip,
    });

    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Authentication required',
    });
  }
  next(err);
});

// ============================================
// ROUTE HANDLERS WITH PROPER ERROR HANDLING
// ============================================

// GOOD: Wrap async handlers to catch errors
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// GOOD: Example route with proper error handling
app.get('/api/users/:id', asyncHandler(async (req, res) => {
  const { id } = req.params;

  // Validate input
  if (!id || id.length === 0) {
    throw new ValidationError('User ID is required', { field: 'id' });
  }

  // Fetch user
  const user = await User.findById(id);

  if (!user) {
    throw new NotFoundError('User not found');
  }

  // Return user data
  res.json(user);
}));

// GOOD: Handle authorization errors
app.delete('/api/users/:id', asyncHandler(async (req, res) => {
  const { id } = req.params;

  // Check authentication
  if (!req.user) {
    throw new UnauthorizedError('Login required');
  }

  // Fetch user
  const user = await User.findById(id);

  if (!user) {
    throw new NotFoundError('User not found');
  }

  // Check authorization
  if (req.user.id !== id && req.user.role !== 'admin') {
    throw new ForbiddenError('Cannot delete other users');
  }

  // Delete user
  await User.deleteOne({ _id: id });

  res.json({ message: 'User deleted' });
}));

// ============================================
// 404 HANDLER
// ============================================

// GOOD: Handle 404 for undefined routes
app.use((req, res) => {
  logger.warn({
    message: '404 Not Found',
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
  });

  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.method} ${req.originalUrl} not found`,
  });
});

// ============================================
// UNCAUGHT EXCEPTION HANDLER
// ============================================

// GOOD: Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  logger.error({
    message: 'Uncaught Exception',
    error: err.message,
    stack: err.stack,
  });

  // Gracefully exit process
  process.exit(1);
});

// GOOD: Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error({
    message: 'Unhandled Rejection',
    reason: reason instanceof Error ? reason.message : reason,
    promise: promise,
  });

  // In production, exit the process
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

// ============================================
// ENVIRONMENT-SPECIFIC ERROR RESPONSES
// ============================================

// GOOD: Different error responses based on environment
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || 500;

  const response = {
    error: err.name || 'Internal Server Error',
    message: process.env.NODE_ENV === 'production'
      ? 'An unexpected error occurred'
      : err.message,
  };

  // Include stack trace only in development
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }

  // Include error code for bug tracking
  if (process.env.NODE_ENV === 'production') {
    response.errorId = `ERR-${Date.now()}`;
    logger.error({
      errorId: response.errorId,
      message: err.message,
      stack: err.stack,
      url: req.originalUrl,
    });
  }

  res.status(statusCode).json(response);
});

// BAD: Exposing stack traces and internal errors
app.use((err, req, res, next) => {
  res.status(500).json({
    error: err.message, // Exposes implementation details
    stack: err.stack, // Exposes code structure
    sql: err.sql, // Exposes database queries
  });
});

// BAD: Swallowing errors silently
app.get('/api/data', async (req, res) => {
  try {
    const data = await database.query('SELECT * FROM users');
    res.json(data);
  } catch (err) {
    // No error handling - silently fails
    res.json({});
  }
});
```

### Error Logging Best Practices

| Log Level | Use Case | Sensitive Data |
|-----------|----------|-----------------|
| **ERROR** | Failed transactions, auth failures, database errors | Yes, log details |
| **WARN** | Validation failures, deprecated API usage | Partial, sanitize PII |
| **INFO** | Request/response summary, business events | No, general info |
| **DEBUG** | Detailed execution flow, variable values | No, dev only |

### Error Response Guidelines

```javascript
// GOOD: Structured error response
{
  "error": "BadRequest",
  "message": "Email already exists",
  "statusCode": 400,
  "details": {
    "field": "email",
    "value": "user@example.com"
  }
}

// BAD: Too much information
{
  "error": "TypeError: Cannot read property 'email' of undefined",
  "stack": "at getUserByEmail (db.js:45:12)...",
  "query": "SELECT * FROM users WHERE email = 'user@example.com'"
}
```

