## 8. Poor Error Handling & Information Disclosure

### Vulnerability Description
Verbose error messages or stack traces exposed to users can reveal sensitive system information useful for attacks.

### Examples

**Vulnerable Code:**
```javascript
// Exposes stack trace to client
app.get('/data', (req, res) => {
  try {
    const data = JSON.parse(req.body);
  } catch (err) {
    res.status(500).json({ error: err.stack }); // Dangerous!
  }
});

// Reveals database schema information
app.post('/login', async (req, res) => {
  try {
    const user = await User.findOne({ email: req.body.email });
  } catch (err) {
    res.status(500).json({ 
      error: 'Database error', 
      query: err.sql, // Exposes SQL query!
      details: err.message 
    });
  }
});
```

### Mitigation Strategies

**1. Generic Error Messages:**
```javascript
// Production error handler
app.use((err, req, res, next) => {
  console.error(err); // Log detailed errors server-side only

  if (process.env.NODE_ENV === 'production') {
    res.status(err.status || 500).json({
      error: 'An error occurred processing your request'
    });
  } else {
    res.status(err.status || 500).json({
      error: err.message,
      stack: err.stack // Only in development
    });
  }
});
```

**2. Structured Logging:**
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  res.status(500).json({ error: 'Internal Server Error' });
});
```

**3. Input Validation Error Messages:**
```javascript
const { body, validationResult } = require('express-validator');

app.post('/register', [
  body('email').isEmail().withMessage('Invalid email format'),
  body('password').isLength({ min: 8 }).withMessage('Password too short')
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      errors: errors.array().map(e => ({
        field: e.param,
        message: e.msg  // Generic message, not system details
      }))
    });
  }
});
```

---

## 9. Insecure Deserialization

### Vulnerability Description
Deserializing untrusted data can lead to arbitrary code execution or object injection attacks.

### Examples

**Vulnerable Code:**
```javascript
// Using eval - NEVER DO THIS
const userData = req.body.data;
eval(userData); // Arbitrary code execution!

// Using pickle-like serialization
const pickle = require('node-pickle');
const obj = pickle.loads(req.body.serialized); // Unsafe!

// Using function constructor
const userFunction = new Function(req.body.code);
userFunction(); // Code execution!
```

### Mitigation Strategies

**1. JSON-Based Serialization Only:**
```javascript
// Safe approach - JSON only
app.post('/api/data', (req, res) => {
  try {
    const data = JSON.parse(req.body); // Safe parsing
    // Validate and process data
  } catch (err) {
    res.status(400).json({ error: 'Invalid JSON' });
  }
});
```

**2. Schema Validation:**
```javascript
const Joi = require('joi');

const schema = Joi.object({
  name: Joi.string().alphanum().min(3).max(30).required(),
  email: Joi.string().email().required(),
  age: Joi.number().integer().min(18).max(100)
});

app.post('/user', (req, res) => {
  const { error, value } = schema.validate(req.body);
  if (error) {
    return res.status(400).json({ error: error.details });
  }
  // Safe data in 'value'
});
```

**3. Avoid Dangerous Functions:**
```javascript
// Bad - Never use these with user input
// eval()
// Function()
// JSON.parse() with custom revivers that execute code
// require() with user-controlled paths
// child_process.exec() with user input

// Good alternatives
const vm = require('vm');

// If you must execute user code, use a sandboxed environment
const sandbox = { console };
vm.runInNewContext(userCode, sandbox, { timeout: 5000 });
```

---

## 10. Insufficient Logging & Monitoring

### Vulnerability Description
Without proper logging and monitoring, security incidents go undetected, and attackers can operate without discovery.

### Examples

**Vulnerable Code:**
```javascript
// No logging
app.post('/login', (req, res) => {
  // No record of who's attempting to login
  authenticateUser(req.body);
});

// Missing security event logging
app.delete('/user/:id', (req, res) => {
  // No audit trail for who deleted what
  db.delete(req.params.id);
});
```

### Mitigation Strategies

**1. Comprehensive Security Logging:**
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'security.log' }),
    new winston.transports.Console()
  ]
});

// Log authentication attempts
app.post('/login', async (req, res) => {
  const result = await authenticateUser(req.body);

  logger.info({
    event: 'login_attempt',
    username: req.body.username,
    success: result.success,
    ip: req.ip,
    userAgent: req.get('user-agent'),
    timestamp: new Date()
  });

  if (!result.success) {
    logger.warn({
      event: 'failed_login',
      username: req.body.username,
      attempts: incrementAttempts(req.ip),
      ip: req.ip
    });
  }
});

// Log authorization failures
const checkAdmin = (req, res, next) => {
  if (req.user.role !== 'admin') {
    logger.warn({
      event: 'unauthorized_access_attempt',
      user: req.user.id,
      endpoint: req.path,
      role: req.user.role,
      ip: req.ip
    });
    return res.status(403).json({ error: 'Forbidden' });
  }
  next();
};

// Log data modifications
app.post('/data', (req, res) => {
  const id = db.save(req.body);

  logger.info({
    event: 'data_created',
    dataId: id,
    user: req.user.id,
    timestamp: new Date()
  });
});
```

**2. Real-Time Alerting:**
```javascript
const alerting = {
  checkSuspiciousActivity: (logs) => {
    const failedLogins = logs.filter(
      log => log.event === 'failed_login' 
        && log.timestamp > Date.now() - 5 * 60 * 1000 // Last 5 minutes
    );

    if (failedLogins.length > 5) {
      sendAlert({
        level: 'HIGH',
        message: `Multiple failed login attempts from ${failedLogins[0].ip}`,
        count: failedLogins.length
      });
    }
  }
};
```

**3. Centralized Log Management:**
```javascript
// Using ELK Stack (Elasticsearch, Logstash, Kibana)
const elasticsearch = require('elasticsearch');

const client = new elasticsearch.Client({
  hosts: ['localhost:9200']
});

const esTransport = {
  log: (msg) => {
    client.index({
      index: 'logs',
      body: msg
    });
  }
};

// Or use third-party services
const bunyan = require('bunyan');
const logglyBunyan = require('bunyan-loggly');

const logger = bunyan.createLogger({
  name: 'myapp',
  streams: [
    {
      type: 'raw',
      stream: logglyBunyan.createStream({
        token: process.env.LOGGLY_TOKEN
      })
    }
  ]
});
```

